import { Cart } from "./shop/cart.js";
import { formatMoney } from "./shop/money.js";
import { quote } from "./shop/pricing.js";
import { defaultCatalog } from "./shop/products.js";

const cart = new Cart(defaultCatalog());
cart.add("BOOK-01", 1);
const q = quote(cart.items(), "US");
console.log(`quote lines=[BOOK-01 x1 @10.00] merchandise=${formatMoney(q.merchandise)} tax=${formatMoney(q.tax)} total=${formatMoney(q.total)}`);
const expected = 83; // provider: 10.00 * 8.25% = 0.825, rounded half-up
if (q.tax !== expected) {
  throw new Error(`tax mismatch ours=${formatMoney(q.tax)} provider=${formatMoney(expected)} delta=${(q.tax - expected) / 100}`);
}
